// patchManagementHTMLForCommandCode adds the provider to the existing workbench.
// All anchors must match before changing the bundle; unknown versions stay intact.
func patchManagementHTMLForCommandCode(input string) (string, bool) {
	if strings.Contains(input, "createCommandCodeConfig") {
		return input, true
	}
	if patched, ok := applyOpenCodeGoBundlePatches(input, commandCodeCurrentBundlePatches()); ok {
		return patched, true
	}
	return applyOpenCodeGoBundlePatches(input, commandCodeLegacyBundlePatches())
}

