func EnsureCommandCodeOnDisk(path string) {
	data, err := os.ReadFile(path)
	if err != nil {
		return
	}
	patched, ok := patchManagementHTMLForCommandCode(string(data))
	if !ok {
		log.Debug("command-code panel skipped: unsupported bundle")
		return
	}
	if patched == string(data) {
		return
	}
	if err = atomicWriteFile(path, []byte(patched)); err != nil {
		log.WithError(err).Warn("command-code panel write failed")
	}
}

